package jet.security;
import android.security.keystore.KeyGenParameterSpec;
import java.io.*;
import java.security.*;
import java.security.cert.Certificate;
import java.security.spec.*;
import java.util.*;
import javax.crypto.*;

/**
 * "AndroidKeyStore" JCA provider, software-backed (Linux host): KeyStore + KeyPairGenerator (RSA, EC) + KeyGenerator (AES, HMAC)
 * driven by android.security.keystore.KeyGenParameterSpec. Keys live in the app sandbox (data dir) so they survive restarts.
 * Key material is generated by the platform providers (SunRsaSign / SunEC / SunJCE); no attestation is offered (getAttestation*
 * is absent), so server-side checks that require hardware attestation see a software key, exactly like an emulator.
 * iOS: the same SPI maps onto a Keychain backend (kSecClassKey; EC P-256 keys optionally in the Secure Enclave via
 * kSecAttrTokenIDSecureEnclave). Only the Backend implementation changes.
 */
public final class JetAndroidKeyStoreProvider extends Provider {
    public static final String NAME = "AndroidKeyStore";
    public JetAndroidKeyStoreProvider() {
        super(NAME, "1.0", "JET software AndroidKeyStore (Linux host; Keychain on iOS)");
        put("KeyStore.AndroidKeyStore", Spi.class.getName());
        put("KeyPairGenerator.RSA", KpgRsa.class.getName());
        put("KeyPairGenerator.EC", KpgEc.class.getName());
        for (String a : new String[]{"AES", "HmacSHA1", "HmacSHA224", "HmacSHA256", "HmacSHA384", "HmacSHA512", "DESede"})
            put("KeyGenerator." + a, "jet.security.JetAndroidKeyStoreProvider$Kg" + a);
    }
    /** Aliases currently in the software store (harness report). */
    public static synchronized java.util.List<String> jetAliases() { load(); return new java.util.ArrayList<>(STORE.keySet()); }
    private static volatile boolean installed;
    public static synchronized void install() { if (!installed && Security.getProvider(NAME) == null) { Security.addProvider(new JetAndroidKeyStoreProvider()); } installed = true; }

    // ---------- storage backend (software, file in the app sandbox) ----------
    static final class Entry implements Serializable { private static final long serialVersionUID = 1; Key key; PublicKey pub; Date created = new Date(); }
    static final Map<String, Entry> STORE = new LinkedHashMap<>();
    private static boolean loaded;
    private static File file() { return new File(System.getProperty("jet.data.dir", System.getProperty("java.io.tmpdir")), ".jet-androidkeystore.ser"); }
    @SuppressWarnings("unchecked") static synchronized void load() {
        if (loaded) return; loaded = true;
        File f = file(); if (!f.isFile()) return;
        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(f))) { STORE.putAll((Map<String, Entry>) in.readObject()); }
        catch (Exception e) { System.err.println("[AndroidKeyStore] could not read " + f + ": " + e); }
    }
    static synchronized void save() {
        try { File f = file(); f.getParentFile().mkdirs(); try (ObjectOutputStream o = new ObjectOutputStream(new FileOutputStream(f))) { o.writeObject(new LinkedHashMap<>(STORE)); } }
        catch (Exception e) { System.err.println("[AndroidKeyStore] could not persist: " + e); }
    }
    static synchronized void put(String alias, Key k, PublicKey pub) { load(); Entry e = new Entry(); e.key = k; e.pub = pub; STORE.put(alias, e); save(); }

    /** Certificate stand-in carrying the public key (Android returns a self-signed placeholder certificate for generated keys). */
    static final class SelfCert extends Certificate {
        private final PublicKey pub; SelfCert(PublicKey p) { super("X.509"); pub = p; }
        public byte[] getEncoded() { return pub.getEncoded(); }
        public void verify(PublicKey key) throws SignatureException { if (!key.equals(pub)) throw new SignatureException("not self-signed by this key"); }
        public void verify(PublicKey key, String sigProvider) throws SignatureException { verify(key); }
        public String toString() { return "AndroidKeyStore placeholder certificate for " + pub.getAlgorithm() + " key"; }
        public PublicKey getPublicKey() { return pub; }
        @Override public boolean equals(Object o) { return o instanceof SelfCert && ((SelfCert) o).pub.equals(pub); }
        @Override public int hashCode() { return pub.hashCode(); }
        protected Object writeReplace() { return this; }
    }

    public static final class Spi extends KeyStoreSpi {
        public Spi() { load(); }
        private static Entry e(String a) { synchronized (JetAndroidKeyStoreProvider.class) { return STORE.get(a); } }
        public Key engineGetKey(String alias, char[] password) { Entry e = e(alias); return e == null ? null : e.key; }
        public Certificate[] engineGetCertificateChain(String alias) { Entry e = e(alias); return e == null || e.pub == null ? null : new Certificate[]{new SelfCert(e.pub)}; }
        public Certificate engineGetCertificate(String alias) { Entry e = e(alias); return e == null || e.pub == null ? null : new SelfCert(e.pub); }
        public Date engineGetCreationDate(String alias) { Entry e = e(alias); return e == null ? null : e.created; }
        public void engineSetKeyEntry(String alias, Key key, char[] pw, Certificate[] chain) { put(alias, key, chain != null && chain.length > 0 ? chain[0].getPublicKey() : null); }
        public void engineSetKeyEntry(String alias, byte[] key, Certificate[] chain) throws KeyStoreException { throw new KeyStoreException("encoded key import not supported"); }
        public void engineSetCertificateEntry(String alias, Certificate cert) { put(alias, null, cert.getPublicKey()); }
        public void engineDeleteEntry(String alias) { synchronized (JetAndroidKeyStoreProvider.class) { STORE.remove(alias); save(); } }
        public Enumeration<String> engineAliases() { synchronized (JetAndroidKeyStoreProvider.class) { return Collections.enumeration(new ArrayList<>(STORE.keySet())); } }
        public boolean engineContainsAlias(String alias) { return e(alias) != null; }
        public int engineSize() { synchronized (JetAndroidKeyStoreProvider.class) { return STORE.size(); } }
        public boolean engineIsKeyEntry(String alias) { Entry e = e(alias); return e != null && e.key != null; }
        public boolean engineIsCertificateEntry(String alias) { Entry e = e(alias); return e != null && e.key == null; }
        public String engineGetCertificateAlias(Certificate cert) { synchronized (JetAndroidKeyStoreProvider.class) { for (Map.Entry<String, Entry> m : STORE.entrySet()) if (m.getValue().pub != null && m.getValue().pub.equals(cert.getPublicKey())) return m.getKey(); } return null; }
        public void engineStore(OutputStream stream, char[] password) { save(); }
        public void engineLoad(InputStream stream, char[] password) throws IOException { if (stream != null) throw new IllegalArgumentException("InputStream not supported"); load(); }
        public void engineLoad(KeyStore.LoadStoreParameter p) { load(); }
        /** AndroidKeyStore entries need no password (ProtectionParameter is ignored, as on Android). */
        @Override public KeyStore.Entry engineGetEntry(String alias, KeyStore.ProtectionParameter prot) throws UnrecoverableEntryException {
            Entry e = e(alias); if (e == null) return null;
            if (e.key instanceof SecretKey) return new KeyStore.SecretKeyEntry((SecretKey) e.key);
            if (e.key instanceof PrivateKey) return new KeyStore.PrivateKeyEntry((PrivateKey) e.key, new Certificate[]{new SelfCert(e.pub)});
            if (e.key == null && e.pub != null) return new KeyStore.TrustedCertificateEntry(new SelfCert(e.pub));
            throw new UnrecoverableEntryException("unsupported entry for " + alias);
        }
        @Override public boolean engineEntryInstanceOf(String alias, Class<? extends KeyStore.Entry> c) {
            Entry e = e(alias); if (e == null) return false;
            if (c == KeyStore.SecretKeyEntry.class) return e.key instanceof SecretKey;
            if (c == KeyStore.PrivateKeyEntry.class) return e.key instanceof PrivateKey;
            if (c == KeyStore.TrustedCertificateEntry.class) return e.key == null;
            return false;
        }
    }

    static abstract class Kpg extends KeyPairGeneratorSpi {
        private final String alg; private KeyGenParameterSpec spec; private SecureRandom rnd;
        Kpg(String alg) { this.alg = alg; }
        public void initialize(int keysize, SecureRandom random) { throw new IllegalArgumentException("AndroidKeyStore requires a KeyGenParameterSpec"); }
        public void initialize(AlgorithmParameterSpec params, SecureRandom random) throws InvalidAlgorithmParameterException {
            if (!(params instanceof KeyGenParameterSpec)) throw new InvalidAlgorithmParameterException("Unsupported params class: " + (params == null ? null : params.getClass().getName()) + ". Supported: KeyGenParameterSpec");
            spec = (KeyGenParameterSpec) params; rnd = random;
        }
        public KeyPair generateKeyPair() {
            if (spec == null) throw new IllegalStateException("Not initialized");
            try {
                KeyPairGenerator g = KeyPairGenerator.getInstance(alg, alg.equals("EC") ? "SunEC" : "SunRsaSign");
                AlgorithmParameterSpec ap = spec.getAlgorithmParameterSpec();
                if (ap != null) g.initialize(ap, rnd != null ? rnd : new SecureRandom());
                else if (alg.equals("EC")) g.initialize(new ECGenParameterSpec(spec.getKeySize() == 384 ? "secp384r1" : spec.getKeySize() == 521 ? "secp521r1" : "secp256r1"));
                else g.initialize(spec.getKeySize() > 0 ? spec.getKeySize() : 2048);
                KeyPair kp = g.generateKeyPair();
                put(spec.getKeystoreAlias(), kp.getPrivate(), kp.getPublic());
                return kp;
            } catch (GeneralSecurityException e) { throw new ProviderException("AndroidKeyStore key generation failed", e); }
        }
    }
    public static final class KpgRsa extends Kpg { public KpgRsa() { super("RSA"); } }
    public static final class KpgEc extends Kpg { public KpgEc() { super("EC"); } }

    static abstract class Kg extends KeyGeneratorSpi {
        private final String alg; private final int defSize; private KeyGenParameterSpec spec;
        Kg(String alg, int defSize) { this.alg = alg; this.defSize = defSize; }
        protected void engineInit(SecureRandom random) { throw new UnsupportedOperationException("AndroidKeyStore requires a KeyGenParameterSpec"); }
        protected void engineInit(int keysize, SecureRandom random) { throw new UnsupportedOperationException("AndroidKeyStore requires a KeyGenParameterSpec"); }
        protected void engineInit(AlgorithmParameterSpec params, SecureRandom random) throws InvalidAlgorithmParameterException {
            if (!(params instanceof KeyGenParameterSpec)) throw new InvalidAlgorithmParameterException("Cannot initialize without a KeyGenParameterSpec");
            spec = (KeyGenParameterSpec) params;
        }
        protected SecretKey engineGenerateKey() {
            if (spec == null) throw new IllegalStateException("Not initialized");
            try {
                KeyGenerator g = KeyGenerator.getInstance(alg, "SunJCE");
                g.init(spec.getKeySize() > 0 ? spec.getKeySize() : defSize);
                SecretKey k = g.generateKey(); put(spec.getKeystoreAlias(), k, null); return k;
            } catch (GeneralSecurityException e) { throw new ProviderException("AndroidKeyStore key generation failed", e); }
        }
    }
    public static final class KgAES extends Kg { public KgAES() { super("AES", 256); } }
    public static final class KgDESede extends Kg { public KgDESede() { super("DESede", 168); } }
    public static final class KgHmacSHA1 extends Kg { public KgHmacSHA1() { super("HmacSHA1", 160); } }
    public static final class KgHmacSHA224 extends Kg { public KgHmacSHA224() { super("HmacSHA224", 224); } }
    public static final class KgHmacSHA256 extends Kg { public KgHmacSHA256() { super("HmacSHA256", 256); } }
    public static final class KgHmacSHA384 extends Kg { public KgHmacSHA384() { super("HmacSHA384", 384); } }
    public static final class KgHmacSHA512 extends Kg { public KgHmacSHA512() { super("HmacSHA512", 512); } }
}
